{
  "name": "Wi‑Fi连接配置模型",
  "name_en": "Wi-Fi Connection Configuration Model",
  "manufacturer": "Mobile Industrial Robots (MiR)",
  "description": "这是一个非物理的软件数据模型，用于在 MiR100 相关客户端/API 中表示或提交 Wi‑Fi 连接参数。它保存 SSID、安全方式、设备名、IP 地址、网关、子网掩码和 DNS 等网络配置，适合实验室移动机器人或自动化系统的网络接入配置场景，本身不直接控制硬件。",
  "description_en": "This is a non-physical software data model used in a MiR100-related client/API to represent or submit Wi-Fi connection settings. It stores network configuration such as SSID, security mode, device name, IP address, gateway, netmask, and DNS for network setup of laboratory mobile robots or automation systems, but does not directly control hardware.",
  "actions": [
    {
      "action_name": "auto-address",
      "description": "获取或设置 Wi‑Fi 连接的地址。",
      "description_en": "Get or set the Wi-Fi connection address."
    },
    {
      "action_name": "auto-device",
      "description": "获取或设置 Wi‑Fi 连接使用的设备名。",
      "description_en": "Get or set the device name used for the Wi-Fi connection."
    },
    {
      "action_name": "auto-dns",
      "description": "获取或设置 Wi‑Fi 连接的 DNS 配置。",
      "description_en": "Get or set the DNS configuration for the Wi-Fi connection."
    },
    {
      "action_name": "auto-gateway",
      "description": "获取或设置 Wi‑Fi 连接的网关。",
      "description_en": "Get or set the gateway for the Wi-Fi connection."
    },
    {
      "action_name": "auto-netmask",
      "description": "获取或设置 Wi‑Fi 连接的子网掩码。",
      "description_en": "Get or set the netmask for the Wi-Fi connection."
    },
    {
      "action_name": "auto-security",
      "description": "获取或设置 Wi‑Fi 连接的安全方式。",
      "description_en": "Get or set the security mode for the Wi-Fi connection."
    },
    {
      "action_name": "auto-ssid",
      "description": "获取或设置 Wi‑Fi 连接的 SSID。",
      "description_en": "Get or set the SSID for the Wi-Fi connection."
    },
    {
      "action_name": "auto-to_dict",
      "description": "将该 Wi‑Fi 连接配置转换为字典。",
      "description_en": "Convert this Wi-Fi connection configuration to a dictionary."
    },
    {
      "action_name": "auto-to_str",
      "description": "返回该 Wi‑Fi 连接配置的字符串表示。",
      "description_en": "Return the string representation of this Wi-Fi connection configuration."
    }
  ],
  "tag_hints": [
    "Wi-Fi configuration",
    "network settings",
    "SSID",
    "IP addressing",
    "DNS gateway netmask",
    "MiR100 API model",
    "mobile robot networking"
  ]
}

